//! The Hurco library (data/machines/hurco.toml, generated by tools/machines/hurco.py from Hurco's
//! public line cards): real and cited, the published numbers in place, the card's own
//! inconsistencies recorded as conflicts, and a tilted-head job on the VMX42SRTi.
use forge_machine::collide;
use forge_machine::def::{CiteStatus, Kind, MachineDef};
use forge_machine::gcode::Control;
use forge_machine::library::{builtin_files, builtin_named};
use forge_machine::sim::{self, Cut, Setup, SimTool};

#[test]
fn hurco_records_are_real_and_cited() {
    let ms: Vec<MachineDef> = builtin_files()
        .into_iter()
        .filter(|(_, f)| f == "builtin/hurco.toml")
        .map(|(m, _)| m)
        .collect();
    assert_eq!(ms.len(), 18);
    for m in &ms {
        assert!(m.real, "{}", m.name);
        for p in m.cite_paths() {
            assert!(m.cites.iter().any(|c| c.path == p), "{}: {p}", m.name);
        }
    }
    let m = builtin_named("hurco-vm10i").unwrap();
    assert_eq!(m.joint("X").unwrap().range, [-660.0, 0.0]);
    assert_eq!(m.joint("X").unwrap().rapid, 28000.0);
    assert_eq!(m.spindles[0].nose[2], 102.0 + 508.0); // nose to table 4 in at the bottom of 20 in Z
    let c = m.changer.as_ref().unwrap();
    assert_eq!((c.pockets, c.max_tool_kg), (24, 7.0));
    // the VM20i's printed travel "40 in / 1,106 mm" is a conflict; the record holds 1,016
    let v = builtin_named("hurco-vm20i").unwrap();
    assert_eq!(v.joint("X").unwrap().range, [-1016.0, 0.0]);
    assert!(
        v.cites
            .iter()
            .any(|c| c.path == "joint.X.range" && c.status == CiteStatus::Conflict)
    );
    let s = builtin_named("hurco-vmx42srti").unwrap();
    assert_eq!(s.kind, Kind::HeadTable);
    assert_eq!(s.joint("B").unwrap().range, [-92.0, 92.0]);
    assert_eq!(s.joint("C").unwrap().rapid, 36000.0); // 100 rpm
    let t = builtin_named("hurco-tm10i").unwrap();
    assert_eq!(t.kind, Kind::Lathe);
    assert_eq!(t.spindles[0].rpm[1], 3000.0);
}

#[test]
fn vmx42srti_tilted_head_job() {
    let m = builtin_named("hurco-vmx42srti").unwrap();
    let c = Control::for_dialect(&m, "fanuc", 1).unwrap();
    let mut s = Setup::new(&m, c).unwrap();
    // letters in definition order: Y X Z B C; the spindle over the rotary table at mid-travel
    let ix = |ch| s.control.letters.iter().position(|&l| l == ch).unwrap();
    let mut w = vec![0.0; 5];
    w[ix('X')] = -533.5;
    w[ix('Y')] = -305.0;
    w[ix('Z')] = -620.0;
    s.wcs = vec![(54, w)];
    s.tools = vec![SimTool {
        t: 1,
        name: "ball-10".into(),
        tip: [0.0, 0.0, -120.0],
        body: vec![(5.0, 0.0, 30.0), (12.0, 30.0, 120.0)],
        cut: Cut::Mill { r: 5.0, corner: 5.0 },
    }];
    s.h = vec![(1, 120.0)];
    s.start_tool = Some(1);
    let prog = "G90 G21 G54\nG43 H1\nG0 X0 Y0 Z300. B0 C0\nB30. C45.\nG1 X-40. Z250. F2000.\nX40.\nG0 Z350.\nB0 C0\n";
    let tl = sim::simulate(prog, &s).unwrap();
    assert!(tl.violations.is_empty(), "{:?}", tl.violations);
    assert!(collide::check(&s, &tl, &[]).contacts.is_empty());
    // past the published +/-92 deg: an overtravel
    let tl = sim::simulate("G90 G21 G54\nG43 H1\nG0 X0 Y0 Z300.\nB95.\n", &s).unwrap();
    assert!(!tl.violations.is_empty());
}
